-- Assignment 2 authentication schema changes for PostgreSQL.
-- Run this against the existing database before using the Assignment 2 auth endpoints.
-- This script preserves Assignment 1 data and intentionally does not seed admin credentials.

CREATE TABLE IF NOT EXISTS "SystemAccount" (
    "AccountID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FullName" character varying(100) NOT NULL,
    "Email" character varying(255) NOT NULL,
    "PasswordHash" character varying(500) NOT NULL,
    "Role" integer NOT NULL DEFAULT 0,
    "CreatedDate" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_SystemAccount_Role" CHECK ("Role" IN (0, 1))
);

CREATE UNIQUE INDEX IF NOT EXISTS "SystemAccount_Email_key"
    ON "SystemAccount" ("Email");

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'Task'
          AND column_name = 'CreatedByAccountID'
    ) THEN
        ALTER TABLE "Task" ADD COLUMN "CreatedByAccountID" integer NULL;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "IX_Task_CreatedByAccountID"
    ON "Task" ("CreatedByAccountID");

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'Task'
          AND column_name = 'UpdatedByAccountID'
    ) THEN
        ALTER TABLE "Task" ADD COLUMN "UpdatedByAccountID" integer NULL;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "IX_Task_UpdatedByAccountID"
    ON "Task" ("UpdatedByAccountID");

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'FK_Task_SystemAccount_CreatedBy'
    ) THEN
        ALTER TABLE "Task"
            ADD CONSTRAINT "FK_Task_SystemAccount_CreatedBy"
            FOREIGN KEY ("CreatedByAccountID")
            REFERENCES "SystemAccount" ("AccountID")
            ON DELETE RESTRICT;
    END IF;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'FK_Task_SystemAccount_UpdatedBy'
    ) THEN
        ALTER TABLE "Task"
            ADD CONSTRAINT "FK_Task_SystemAccount_UpdatedBy"
            FOREIGN KEY ("UpdatedByAccountID")
            REFERENCES "SystemAccount" ("AccountID")
            ON DELETE SET NULL;
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS "RefreshToken" (
    "RefreshTokenID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AccountID" integer NOT NULL,
    "TokenHash" character varying(128) NOT NULL,
    "ExpiresAt" timestamp without time zone NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "RevokedAt" timestamp without time zone NULL,
    "ReplacedByTokenHash" character varying(128) NULL,
    CONSTRAINT "FK_RefreshToken_SystemAccount"
        FOREIGN KEY ("AccountID")
        REFERENCES "SystemAccount" ("AccountID")
        ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "RefreshToken_TokenHash_key"
    ON "RefreshToken" ("TokenHash");

CREATE INDEX IF NOT EXISTS "IX_RefreshToken_AccountID"
    ON "RefreshToken" ("AccountID");
